import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Agent 产品与交互设计","description":"沿任务委托、确认、执行、结果和恢复的生命周期设计 Agent 交互，并处理记忆、信任、多 Agent 与可访问性。","frontmatter":{"title":"Agent 产品与交互设计","description":"沿任务委托、确认、执行、结果和恢复的生命周期设计 Agent 交互，并处理记忆、信任、多 Agent 与可访问性。","verified_at":"2026-08-06","source":["https://www.w3.org/TR/WCAG22/","https://www.w3.org/WAI/ARIA/apg/","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/technology-product-design/agent-product-interaction.md","filePath":"py-agent/architecture/technology-product-design/agent-product-interaction.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/technology-product-design/agent-product-interaction.md"};function o(l,a,d,h,s,c){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="agent-产品与交互设计" tabindex="-1">Agent 产品与交互设计 <a class="header-anchor" href="#agent-产品与交互设计" aria-label="Permalink to &quot;Agent 产品与交互设计&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 产品不是“聊天框 + 发送按钮”。用户实际上在委托一项任务：需要知道系统能做什么、将使用哪些数据和工具、运行到哪里、哪些动作尚待确认、结果依据是什么，以及失败后能否继续。</p><p>本章沿一次任务的生命周期组织产品状态和界面责任。人工审批的权限、令牌和恢复机制见<a href="/py-agent/architecture/technology-product-design/human-in-loop-trust-design">人在回路与信任设计</a>，SSE、WebSocket 和断线续传的实现见<a href="/py-agent/application/services-api/streaming-realtime-communication">流式与实时通信</a>。</p><h2 id="_1-交互模型" tabindex="-1">1. 交互模型 <a class="header-anchor" href="#_1-交互模型" aria-label="Permalink to &quot;1. 交互模型&quot;">​</a></h2><h3 id="_1-1-从对话转向任务" tabindex="-1">1.1 从对话转向任务 <a class="header-anchor" href="#_1-1-从对话转向任务" aria-label="Permalink to &quot;1.1 从对话转向任务&quot;">​</a></h3><p>消息是输入方式，任务才是需要完成和验收的对象。一次任务至少具有目标、输入、状态、产物、动作、错误和完成证据；刷新页面后这些信息仍应可查询。</p><h3 id="_1-2-任务生命周期" tabindex="-1">1.2 任务生命周期 <a class="header-anchor" href="#_1-2-任务生命周期" aria-label="Permalink to &quot;1.2 任务生命周期&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft -&gt; ready -&gt; queued -&gt; running</span></span>
<span class="line"><span>                    |          |</span></span>
<span class="line"><span>                    |          +-&gt; waiting_for_input</span></span>
<span class="line"><span>                    |          +-&gt; waiting_for_approval</span></span>
<span class="line"><span>                    |          +-&gt; cancelling</span></span>
<span class="line"><span>                    v</span></span>
<span class="line"><span>          succeeded / partially_succeeded / failed / cancelled</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>界面状态必须来自后端事实，而不是根据已生成多少文字猜测。所有终态都应说明结果是否可用以及是否发生外部动作。</p><h3 id="_1-3-自动化等级" tabindex="-1">1.3 自动化等级 <a class="header-anchor" href="#_1-3-自动化等级" aria-label="Permalink to &quot;1.3 自动化等级&quot;">​</a></h3><p>同一个 Agent 可以同时包含建议、可编辑草稿、确认后执行和受限自动执行。自动化等级应附着于具体动作；“这个 Agent 是全自动的”无法表达不同工具的风险差异。</p><h3 id="_1-4-产品承诺" tabindex="-1">1.4 产品承诺 <a class="header-anchor" href="#_1-4-产品承诺" aria-label="Permalink to &quot;1.4 产品承诺&quot;">​</a></h3><p>设计前明确三类承诺：系统支持的任务、失败时的处置、用户可获得的控制。文案不能暗示系统拥有不存在的实时知识、权限或人工审核。</p><h2 id="_2-委托前" tabindex="-1">2. 委托前 <a class="header-anchor" href="#_2-委托前" aria-label="Permalink to &quot;2. 委托前&quot;">​</a></h2><h3 id="_2-1-能力与边界" tabindex="-1">2.1 能力与边界 <a class="header-anchor" href="#_2-1-能力与边界" aria-label="Permalink to &quot;2.1 能力与边界&quot;">​</a></h3><p>入口直接呈现可完成的任务、所需数据、可用工具和不能处理的范围。用任务模板或示例降低学习成本，而不是要求用户掌握 Prompt 技巧。</p><h3 id="_2-2-结构化输入" tabindex="-1">2.2 结构化输入 <a class="header-anchor" href="#_2-2-结构化输入" aria-label="Permalink to &quot;2.2 结构化输入&quot;">​</a></h3><p>自然语言适合描述目标和背景；日期、金额、资源、收件人和权限范围使用表单、选择器或可校验字段。关键参数不能只靠模型从长文本猜测。</p><h3 id="_2-3-文件与上下文" tabindex="-1">2.3 文件与上下文 <a class="header-anchor" href="#_2-3-文件与上下文" aria-label="Permalink to &quot;2.3 文件与上下文&quot;">​</a></h3><p>上传前显示类型、大小和用途，上传后显示识别状态、处理范围和删除入口。历史会话、记忆和文件应按任务选择，不默认把所有可获得信息加入上下文。</p><h3 id="_2-4-澄清" tabindex="-1">2.4 澄清 <a class="header-anchor" href="#_2-4-澄清" aria-label="Permalink to &quot;2.4 澄清&quot;">​</a></h3><p>只询问会显著改变结果且无法安全采用默认值的信息。问题应指出缺什么、为什么需要、有哪些可选答案；连续开放式追问会把系统的不确定性转嫁给用户。</p><h2 id="_3-提交与确认" tabindex="-1">3. 提交与确认 <a class="header-anchor" href="#_3-提交与确认" aria-label="Permalink to &quot;3. 提交与确认&quot;">​</a></h2><h3 id="_3-1-任务摘要" tabindex="-1">3.1 任务摘要 <a class="header-anchor" href="#_3-1-任务摘要" aria-label="Permalink to &quot;3.1 任务摘要&quot;">​</a></h3><p>提交前把自然语言目标规范化为可检查摘要：处理对象、时间范围、数据、预期产物和允许动作。用户应能修改理解错误，而不是等任务完成后返工。</p><h3 id="_3-2-执行预览" tabindex="-1">3.2 执行预览 <a class="header-anchor" href="#_3-2-执行预览" aria-label="Permalink to &quot;3.2 执行预览&quot;">​</a></h3><p>长任务展示主要阶段和可能调用的系统；高风险动作展示规范化参数、影响范围和可逆性。预览描述的是当前计划，不应伪装成不会变化的承诺。</p><h3 id="_3-3-风险匹配的确认" tabindex="-1">3.3 风险匹配的确认 <a class="header-anchor" href="#_3-3-风险匹配的确认" aria-label="Permalink to &quot;3.3 风险匹配的确认&quot;">​</a></h3><p>简单只读问答无需反复确认；发送、删除、付款和权限变更应在动作参数固定后确认。确认成本与风险匹配，才能避免用户形成机械点击习惯。</p><h3 id="_3-4-前台与后台" tabindex="-1">3.4 前台与后台 <a class="header-anchor" href="#_3-4-前台与后台" aria-label="Permalink to &quot;3.4 前台与后台&quot;">​</a></h3><p>预计超出交互等待的任务应在提交时说明可转后台、通知方式和截止时间。关闭页面不应自动取消已接受任务，除非产品明确采用这种语义。</p><h2 id="_4-执行中" tabindex="-1">4. 执行中 <a class="header-anchor" href="#_4-执行中" aria-label="Permalink to &quot;4. 执行中&quot;">​</a></h2><h3 id="_4-1-真实状态" tabindex="-1">4.1 真实状态 <a class="header-anchor" href="#_4-1-真实状态" aria-label="Permalink to &quot;4.1 真实状态&quot;">​</a></h3><p>使用 <code>queued</code>、<code>retrieving</code>、<code>waiting_for_approval</code>、<code>retrying_dependency</code> 等可验证状态。没有可靠分母时不要显示从 0 到 99 的虚假进度条。</p><h3 id="_4-2-流式结果" tabindex="-1">4.2 流式结果 <a class="header-anchor" href="#_4-2-流式结果" aria-label="Permalink to &quot;4.2 流式结果&quot;">​</a></h3><p>流式文本可以降低感知等待，但未完成内容可能被修改或最终失败。生成中内容应有状态标记，完成后再固定可复制结果；关键引用可在验证后展示。</p><h3 id="_4-3-工具活动" tabindex="-1">4.3 工具活动 <a class="header-anchor" href="#_4-3-工具活动" aria-label="Permalink to &quot;4.3 工具活动&quot;">​</a></h3><p>展示对用户有意义的动作摘要，例如“正在查询订单 A100”，隐藏密钥、内部参数和低价值调用噪声。模型的自然语言说明不是工具已执行的证据。</p><h3 id="_4-4-等待与人工介入" tabindex="-1">4.4 等待与人工介入 <a class="header-anchor" href="#_4-4-等待与人工介入" aria-label="Permalink to &quot;4.4 等待与人工介入&quot;">​</a></h3><p>需要输入或审批时，任务进入明确等待态，展示问题、截止时间和当前已完成工作。等待不是失败，也不应继续消耗模型和 Worker 资源。</p><h3 id="_4-5-取消" tabindex="-1">4.5 取消 <a class="header-anchor" href="#_4-5-取消" aria-label="Permalink to &quot;4.5 取消&quot;">​</a></h3><p>取消请求需要传播到模型、工具和后台任务，并返回最终取消结果。已经发送的邮件或创建的退款不会因界面显示“已取消”自动撤销，必须单独说明和补偿。</p><h2 id="_5-结果交付" tabindex="-1">5. 结果交付 <a class="header-anchor" href="#_5-结果交付" aria-label="Permalink to &quot;5. 结果交付&quot;">​</a></h2><h3 id="_5-1-结论与证据" tabindex="-1">5.1 结论与证据 <a class="header-anchor" href="#_5-1-结论与证据" aria-label="Permalink to &quot;5.1 结论与证据&quot;">​</a></h3><p>把结论、来源、假设、冲突和缺失信息分开。引用应定位到支持相邻陈述的片段，而不是只给一个泛化参考列表。</p><h3 id="_5-2-结构化产物" tabindex="-1">5.2 结构化产物 <a class="header-anchor" href="#_5-2-结构化产物" aria-label="Permalink to &quot;5.2 结构化产物&quot;">​</a></h3><p>报告、SQL、代码 Patch、表格和审批建议使用适合领域的视图，支持预览、编辑、下载或提交。聊天气泡不应承载所有复杂产物。</p><h3 id="_5-3-不确定性" tabindex="-1">5.3 不确定性 <a class="header-anchor" href="#_5-3-不确定性" aria-label="Permalink to &quot;5.3 不确定性&quot;">​</a></h3><p>优先说明哪些事实缺失、哪些来源冲突、哪项判断需要用户确认。未经校准的“87% 置信度”会制造虚假精确，不能代替具体证据。</p><h3 id="_5-4-动作回执" tabindex="-1">5.4 动作回执 <a class="header-anchor" href="#_5-4-动作回执" aria-label="Permalink to &quot;5.4 动作回执&quot;">​</a></h3><p>外部动作展示业务系统返回的操作 ID、状态、时间、参数摘要和跟进入口。只有权威系统的回执能够证明“已发送”“已退款”或“已发布”。</p><h3 id="_5-5-下一步" tabindex="-1">5.5 下一步 <a class="header-anchor" href="#_5-5-下一步" aria-label="Permalink to &quot;5.5 下一步&quot;">​</a></h3><p>只提供与当前结果相关的后续动作，例如修改草稿、补齐证据、重新运行失败步骤或转人工。不要用无限推荐把一个已完成任务重新变成开放对话。</p><h2 id="_6-失败与恢复" tabindex="-1">6. 失败与恢复 <a class="header-anchor" href="#_6-失败与恢复" aria-label="Permalink to &quot;6. 失败与恢复&quot;">​</a></h2><h3 id="_6-1-错误分类" tabindex="-1">6.1 错误分类 <a class="header-anchor" href="#_6-1-错误分类" aria-label="Permalink to &quot;6.1 错误分类&quot;">​</a></h3><p>区分输入不足、权限拒绝、外部依赖、超时、预算、安全策略和内部故障。每类错误应给出不同的用户动作，不能统一显示“出错了，请重试”。</p><h3 id="_6-2-保留工作" tabindex="-1">6.2 保留工作 <a class="header-anchor" href="#_6-2-保留工作" aria-label="Permalink to &quot;6.2 保留工作&quot;">​</a></h3><p>失败后保留用户输入、已完成步骤、产物和安全 Checkpoint。恢复入口说明从哪里继续、是否会重新调用工具以及哪些状态可能已经变化。</p><h3 id="_6-3-部分结果" tabindex="-1">6.3 部分结果 <a class="header-anchor" href="#_6-3-部分结果" aria-label="Permalink to &quot;6.3 部分结果&quot;">​</a></h3><p>使用 <code>partially_succeeded</code> 等明确状态，列出已完成、未完成和仍可使用的结果。用户可以补齐、跳过非关键步骤或转人工，而不是丢失全部工作。</p><h3 id="_6-4-重试语义" tabindex="-1">6.4 重试语义 <a class="header-anchor" href="#_6-4-重试语义" aria-label="Permalink to &quot;6.4 重试语义&quot;">​</a></h3><p>只读调用可在有限条件下重试；写动作结果不明时先查询业务状态。重试按钮应告诉用户它会重新计算、继续执行还是只重新获取结果。</p><h3 id="_6-5-反馈" tabindex="-1">6.5 反馈 <a class="header-anchor" href="#_6-5-反馈" aria-label="Permalink to &quot;6.5 反馈&quot;">​</a></h3><p>允许用户针对事实、引用、工具动作和整体任务分别反馈，并关联 Run ID。单个点赞可以表达满意度，却无法直接定位系统应修改哪一层。</p><h2 id="_7-横切设计" tabindex="-1">7. 横切设计 <a class="header-anchor" href="#_7-横切设计" aria-label="Permalink to &quot;7. 横切设计&quot;">​</a></h2><p>生命周期说明任务何时发生什么；以下能力贯穿多个阶段，不应和“输入、执行、结果”并列成另一套时间线。</p><h3 id="_7-1-记忆与个性化" tabindex="-1">7.1 记忆与个性化 <a class="header-anchor" href="#_7-1-记忆与个性化" aria-label="Permalink to &quot;7.1 记忆与个性化&quot;">​</a></h3><p>用户能查看系统记住的内容、来源、用途和有效期，并能编辑、删除或关闭。稳定偏好、历史业务事实和当前任务上下文分开管理；详细机制见<a href="/py-agent/knowledge/memory/memory-model-boundaries">记忆模型与边界</a>。</p><h3 id="_7-2-信任与控制" tabindex="-1">7.2 信任与控制 <a class="header-anchor" href="#_7-2-信任与控制" aria-label="Permalink to &quot;7.2 信任与控制&quot;">​</a></h3><p>明确用户正在与 AI 系统交互，以及人工是否真的审核。草稿、预览、撤销和版本历史降低试错成本；不可逆动作需要更强权限、确认和申诉渠道。</p><h3 id="_7-3-多-agent-可见性" tabindex="-1">7.3 多 Agent 可见性 <a class="header-anchor" href="#_7-3-多-agent-可见性" aria-label="Permalink to &quot;7.3 多 Agent 可见性&quot;">​</a></h3><p>默认展示一个统一任务，不让用户管理内部 Agent 组织。只有角色差异会改变用户决定时才显示，例如“法律复核尚未完成”；内部协作对话和思维文本不应原样暴露。</p><h3 id="_7-4-可访问性" tabindex="-1">7.4 可访问性 <a class="header-anchor" href="#_7-4-可访问性" aria-label="Permalink to &quot;7.4 可访问性&quot;">​</a></h3><p>流式更新使用节制的 <code>aria-live</code>，避免屏幕阅读器逐 Token 朗读；焦点不随新消息跳动。所有动作可键盘操作，状态不只靠颜色，图像、音频和图表提供文本替代，并按 WCAG 2.2 和具体组件模式验证。</p><h2 id="_8-贯穿案例-退款建议与确认" tabindex="-1">8. 贯穿案例：退款建议与确认 <a class="header-anchor" href="#_8-贯穿案例-退款建议与确认" aria-label="Permalink to &quot;8. 贯穿案例：退款建议与确认&quot;">​</a></h2><p>一次完整旅程可以这样呈现：</p><table tabindex="0"><thead><tr><th>阶段</th><th>后端事实</th><th>用户界面</th></tr></thead><tbody><tr><td>委托</td><td>目标为订单 <code>A100</code> 的退款建议</td><td>订单、原因和附件为结构化字段</td></tr><tr><td>提交</td><td>识别到只读订单查询和政策检索</td><td>展示任务摘要；说明不会自动退款</td></tr><tr><td>执行</td><td><code>retrieving_order -&gt; checking_policy</code></td><td>显示真实阶段和已使用数据</td></tr><tr><td>结果</td><td>建议退款 120 元，引用政策 <code>P-17</code></td><td>分开展示建议、证据和缺失项</td></tr><tr><td>动作提案</td><td><code>refund.create(order=A100, amount=120)</code></td><td>展示规范化参数和不可逆影响</td></tr><tr><td>等待</td><td><code>waiting_for_approval</code></td><td>有权专员可批准、修改或拒绝</td></tr><tr><td>完成</td><td>业务系统返回 <code>refund_id=R9001</code></td><td>显示操作回执和跟进入口</td></tr></tbody></table><p>如果创建请求超时，界面进入“结果待确认”，先按幂等键查询业务系统，不直接鼓励用户再次点击。这个案例让消息、状态、证据和动作保持同一条结果链，而不是把 Agent 的自然语言当成所有事实。</p><h2 id="_9-产品评测" tabindex="-1">9. 产品评测 <a class="header-anchor" href="#_9-产品评测" aria-label="Permalink to &quot;9. 产品评测&quot;">​</a></h2><p>联合观察任务成功、完成时间、澄清轮数、取消、恢复、人工接管、动作撤销、引用使用、用户纠正和每成功任务成本。留存、消息数和生成速度不能证明用户目标已经完成。</p><p>可用性测试应检查用户能否回答：系统当前在做什么、结果是否最终、哪个动作尚未执行、失败后会不会重复，以及怎样修改或转人工。高失败 Session 需要沿完整任务旅程复盘，而不只看最后一条消息。</p><h2 id="_10-常见误区" tabindex="-1">10. 常见误区 <a class="header-anchor" href="#_10-常见误区" aria-label="Permalink to &quot;10. 常见误区&quot;">​</a></h2><ol><li><strong>所有任务都使用聊天</strong>：结构化参数和复杂产物难以操作。</li><li><strong>流式 Token 等于进度</strong>：生成速度不代表任务阶段。</li><li><strong>展示模型思维链建立信任</strong>：它不是可靠证据，还可能泄露内部信息。</li><li><strong>每个动作都确认</strong>：确认疲劳会削弱真正高风险控制。</li><li><strong>失败后一律重新开始</strong>：已完成工作和副作用状态可能丢失。</li><li><strong>置信度数字解释一切</strong>：没有校准和具体证据时会误导。</li></ol><h2 id="_11-设计检查表" tabindex="-1">11. 设计检查表 <a class="header-anchor" href="#_11-设计检查表" aria-label="Permalink to &quot;11. 设计检查表&quot;">​</a></h2><ul><li>用户是否理解支持任务、数据用途、自动化等级和失败边界；</li><li>输入、提交、执行、结果和恢复是否形成连续任务生命周期；</li><li>关键参数是否结构化，澄清是否必要且具体；</li><li>进度是否来自真实状态，取消是否有实际传播和终态；</li><li>结果是否区分结论、证据、不确定性和业务动作回执；</li><li>失败是否保留工作并说明重试语义；</li><li>记忆、人工控制和内部多 Agent 是否以用户可控方式呈现；</li><li>动态界面是否经过键盘、屏幕阅读器和多模态替代验证。</li></ul><p>Agent 交互的核心不是让模型显得像人，而是让委托关系清楚：用户知道交给系统什么、系统正在做什么、哪些事实可信、哪些动作需要控制，以及出错后怎样继续。</p>`,87)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
